window.__votdWeek && window.__votdWeek({"week":"2029-02-12","reading":"Doctrine and Covenants 10–11","days":[{"d":"2029-02-12","ref":"D&C 10:4","b":"D&C","c":10,"v":4,"he":"אַל תָּרוּץ מָהֵר וְאַל תַּעֲמֹל יוֹתֵר מִכֹּחֲךָ וּמֵאֲשֶׁר נִתַּן לְךָ לְתַרְגֵּם אַךְ הֱיֵה חָרוּץ עַד הַקֵּץ׃","en":"Do not run faster or labor more than you have strength and means provided to enable you to translate; but be diligent unto the end."},{"d":"2029-02-13","ref":"D&C 10:21","b":"D&C","c":10,"v":21,"he":"וְלִבָּם נִשְׁחָת וּמָלֵא רֶשַׁע וְתוֹעֵבוֹת וְאֹהֲבִים הֵם חֹשֶׁךְ מֵאוֹר כִּי רָעִים מַעֲשֵׂיהֶם עַל־כֵּן לֹא יִשְׁאֲלוּ מִמֶּנִּי׃","en":"And their hearts are corrupt, and full of wickedness and abominations; and they love darkness rather than light, because their deeds are evil; therefore they will not ask of me."},{"d":"2029-02-14","ref":"D&C 10:26","b":"D&C","c":10,"v":26,"he":"וְכֵן מַחֲלִיק לָהֶם וּמוֹלִיכָם עַד סׇחֳבוֹ נַפְשׁוֹתָם לִשְׁאוֹל וְכֵן מְבִיאָם לְהִלָּכֵד בְּפַחָם׃","en":"And thus he flattereth them, and leadeth them along until he draggeth their souls down to hell; and thus he causeth them to catch themselves in their own snare."},{"d":"2029-02-15","ref":"D&C 10:27","b":"D&C","c":10,"v":27,"he":"וְכֵן מְהַלֵּךְ הָלוֹךְ וָשׁוֹב בָּאָרֶץ לְבַקֵּשׁ לְהַשְׁמִיד נַפְשׁוֹת אָדָם׃","en":"And thus he goeth up and down, to and fro in the earth, seeking to destroy the souls of men."},{"d":"2029-02-16","ref":"D&C 11:2","b":"D&C","c":11,"v":2,"he":"הִנֵּה אָנֹכִי אֱלֹהִים הַקְשִׁיבָה לִדְבָרִי אֲשֶׁר חַי הוּא וְתַקִּיף חַד מֵחֶרֶב פִּיפִיּוֹת לְהַבְדִּיל בֵּין פֶּרֶק וָמֹחַ עַל־כֵּן הַקְשִׁיבָה לִדְבָרִי׃","en":"Behold, I am God; give heed to my word, which is quick and powerful, sharper than a two-edged sword, to the dividing asunder of both joints and marrow; therefore give heed unto my word."},{"d":"2029-02-17","ref":"D&C 11:12","b":"D&C","c":11,"v":12,"he":"וְעַתָּה אָמֵן אָמֵן אֲנִי אֹמֵר לְךָ בְּטַח בָּרוּחַ הַמּוֹלִיךְ לַעֲשׂוֹת טוֹב אָכֵן לַעֲשׂוֹת מִשְׁפָּט לְהַצְנֵעַ לֶכֶת לִשְׁפֹּט צֶדֶק וְזֹאת רוּחִי׃","en":"And now, verily, verily, I say unto thee, put your trust in that Spirit which leadeth to do good—yea, to do justly, to walk humbly, to judge righteously; and this is my Spirit."},{"d":"2029-02-18","ref":"D&C 11:19","b":"D&C","c":11,"v":19,"he":"אָכֵן דְּבַק בִּי בְּכׇל־לְבָבְךָ לְמַעַן תַּעֲזֹר לְהוֹצִיא לָאוֹר אֶת־הַדְּבָרִים אֲשֶׁר נֶאֶמְרוּ אָכֵן תִּרְגּוּם מְלַאכְתִּי הִתְאַפֵּק עַד כַּלּוֹתְךָ׃","en":"Yea, cleave unto me with all your heart, that you may assist in bringing to light those things of which has been spoken—yea, the translation of my work; be patient until you shall accomplish it."}]});
